export enum HTMLRenderMode {
    AUTO = "auto",         // Dynamically selects best mode based on browser & renderer
    NATIVE = "native",     // Chrome experimental copyElementImageToTexture WebGPU API
    CSS3D = "css3d",       // High-fidelity DOM overlay synced to camera projection
    RASTER = "raster"      // SVG ForeignObject rasterizer for video export & shadow maps
}

import { Scene, RTHTML, RTVideo, OrbitCameraController, HTMLRenderMode, Vec3 } from "retiam";

const scene = new Scene({ canvas });
new OrbitCameraController(scene.camera, canvas);

// 1. Interactive 3D DOM Terminal
const browser = new RTHTML(12, 8, "https://wikipedia.org", {
    mode: HTMLRenderMode.CSS3D,
    resolution: 1024
});
browser.transform.position = [-7, 0, 0];
browser.transform.rotation.y = Math.PI / 6;
scene.add(browser);

// 2. 3D TV Screen with streaming video
const tv = new RTVideo(16, 9, "/assets/big_buck_bunny.mp4");
tv.transform.position = [7, 0, 0];
scene.add(tv);
